import { describe, expect, it } from "vitest";
import type { Skill, SkillCatalog } from "../../types";
import {
  buildMemoryReferenceIndex,
  buildReferenceIndex,
  tokenizeReferences,
  type ReferenceIndex,
} from "./references";

function makeSkill(overrides: Partial<Skill> = {}): Skill {
  return {
    id: "card_replace",
    name: "Card Replace",
    description: null,
    is_default: false,
    engine_managed: false,
    disabled: false,
    sections: [],
    blocks: {
      main: {
        ordered_block_id: "card_replace__main",
        complete_when: null,
        steps: [],
      },
    },
    referenced_skills: [],
    tool_names: ["lock_card"],
    hidden: false,
    ...overrides,
  };
}

function makeIndex(): ReferenceIndex {
  const skill = makeSkill();
  const catalog: SkillCatalog = {
    card_replace: skill,
    card_disambiguation: makeSkill({ id: "card_disambiguation", blocks: {}, tool_names: [] }),
    report_fraudulent_transaction: makeSkill({
      id: "report_fraudulent_transaction",
      blocks: {
        main: {
          ordered_block_id: "report_fraudulent_transaction__main",
          complete_when: null,
          steps: [],
        },
      },
      tool_names: [],
    }),
  };
  return buildReferenceIndex(skill, catalog);
}

describe("buildReferenceIndex", () => {
  it("indexes skills, blocks and tools with kind-specific targets", () => {
    const index = makeIndex();
    // Skills are referenced by the compiler's @skill.<id> token — a bare
    // skill id is not a reference and must not be indexed.
    expect(index.get("@skill.card_disambiguation")).toEqual({
      kind: "skill",
      target: "card_disambiguation",
    });
    expect(index.get("card_disambiguation")).toBeUndefined();
    expect(index.get("main")).toEqual({ kind: "block", target: "card_replace__main" });
    expect(index.get("lock_card")).toEqual({ kind: "tool", target: "lock_card" });
  });

  it("indexes compiled block flow ids, own and cross-skill", () => {
    const index = makeIndex();
    expect(index.get("card_replace__main")).toEqual({
      kind: "block",
      target: "card_replace__main",
    });
    expect(index.get("report_fraudulent_transaction__main")).toEqual({
      kind: "block",
      target: "report_fraudulent_transaction__main",
    });
  });

  it("keeps tools and @skill tokens from colliding", () => {
    const skill = makeSkill({ tool_names: ["card_replace"] });
    const index = buildReferenceIndex(skill, { card_replace: skill });
    expect(index.get("card_replace")?.kind).toBe("tool");
    expect(index.get("@skill.card_replace")?.kind).toBe("skill");
  });
});

describe("buildMemoryReferenceIndex", () => {
  it("indexes @-prefixed memory mentions in both notations", () => {
    const index = buildMemoryReferenceIndex({
      destination: { value: "Atlantis" },
      "card_replace.replacement_reason": { value: "lost" },
    });
    expect(index.get("@destination")).toEqual({ kind: "memory", target: "destination" });
    expect(index.get("@memory.destination")).toEqual({ kind: "memory", target: "destination" });
    expect(index.get("@memory.card_replace.replacement_reason")).toEqual({
      kind: "memory",
      target: "card_replace.replacement_reason",
    });
  });

  it("returns an empty index when there is no memory", () => {
    expect(buildMemoryReferenceIndex(null).size).toBe(0);
    expect(buildMemoryReferenceIndex(undefined).size).toBe(0);
    expect(buildMemoryReferenceIndex({}).size).toBe(0);
  });
});

function makeMemoryIndex(): ReferenceIndex {
  const index = makeIndex();
  for (const [key, reference] of buildMemoryReferenceIndex({
    "card_replace.replacement_reason": { value: "lost" },
  })) {
    index.set(key, reference);
  }
  return index;
}

describe("tokenizeReferences", () => {
  it("returns the whole text when nothing matches", () => {
    expect(tokenizeReferences("plain prose only", makeIndex())).toEqual([
      { text: "plain prose only" },
    ]);
  });

  it("splits references out of surrounding prose", () => {
    const tokens = tokenizeReferences("Use lock_card to lock the card.", makeIndex());
    expect(tokens).toEqual([
      { text: "Use " },
      { text: "lock_card", reference: { kind: "tool", target: "lock_card" } },
      { text: " to lock the card." },
    ]);
  });

  it("matches @block tokens for the skill's own blocks", () => {
    const tokens = tokenizeReferences("then run @block.main to finish", makeIndex());
    expect(tokens[1]).toEqual({
      text: "@block.main",
      display: "main",
      reference: { kind: "block", target: "card_replace__main" },
    });
  });

  it("matches compiled block ids instead of their skill-id prefix", () => {
    const tokens = tokenizeReferences("activate card_replace__main now", makeIndex());
    expect(tokens).toEqual([
      { text: "activate " },
      { text: "card_replace__main", reference: { kind: "block", target: "card_replace__main" } },
      { text: " now" },
    ]);
  });

  it("matches cross-skill block references", () => {
    const tokens = tokenizeReferences(
      "activate report_fraudulent_transaction__main first",
      makeIndex(),
    );
    expect(tokens[1]).toEqual({
      text: "report_fraudulent_transaction__main",
      reference: { kind: "block", target: "report_fraudulent_transaction__main" },
    });
  });

  it("matches @skill tokens and displays the bare id", () => {
    const tokens = tokenizeReferences("hand off to @skill.card_disambiguation.", makeIndex());
    expect(tokens[1]).toEqual({
      text: "@skill.card_disambiguation",
      display: "card_disambiguation",
      reference: { kind: "skill", target: "card_disambiguation" },
    });
  });

  it("does not highlight bare skill ids (not references for the compiler)", () => {
    const tokens = tokenizeReferences("hand off to card_disambiguation.", makeIndex());
    expect(tokens).toEqual([{ text: "hand off to card_disambiguation." }]);
  });

  it("does not match inside dotted memory paths or identifiers", () => {
    const memoryPath = tokenizeReferences("check session.card_replace.reason now", makeIndex());
    expect(memoryPath).toEqual([{ text: "check session.card_replace.reason now" }]);

    const identifier = tokenizeReferences("not lock_cards or unlock_card", makeIndex());
    expect(identifier).toEqual([{ text: "not lock_cards or unlock_card" }]);
  });

  it("tokenizes an @memory mention and displays the bare key", () => {
    const tokens = tokenizeReferences(
      "confirm @memory.card_replace.replacement_reason before submitting",
      makeMemoryIndex(),
    );
    expect(tokens[1]).toEqual({
      text: "@memory.card_replace.replacement_reason",
      display: "card_replace.replacement_reason",
      reference: { kind: "memory", target: "card_replace.replacement_reason" },
    });
  });

  it("does not tokenize a bare dotted memory path as a memory reference", () => {
    // Only the @-prefixed notation becomes a pill; the bare path is prose.
    expect(
      tokenizeReferences("check card_replace.replacement_reason now", makeMemoryIndex()),
    ).toEqual([{ text: "check card_replace.replacement_reason now" }]);
  });

  it("handles empty index and empty text", () => {
    expect(tokenizeReferences("anything", new Map())).toEqual([{ text: "anything" }]);
    expect(tokenizeReferences("", makeIndex())).toEqual([{ text: "" }]);
  });
});
